import yaml, re

with open('registry.yaml', 'r') as f:
    data = yaml.safe_load(f)

experiments = data.get('experiments', {})
if not experiments:
    print('No experiments key found')
    exit()

# First, list all conclusions
from collections import Counter
conclusions = Counter()
for eid, exp in experiments.items():
    if exp is None:
        continue
    c = exp.get('conclusion', '<none>')
    conclusions[c] += 1
print('Conclusion distribution:')
for c, n in conclusions.most_common():
    print(f'  {c}: {n}')
print()

method_keywords = ['adaptive', 'uniform', 'hybrid', 'gpt2', 'ngram', 'baseline']
param_keywords_tau = re.compile(r'tau(\d+)')
param_keywords_rho = re.compile(r'rho(\d+)')

issues = []
checked = 0

for exp_id, exp in experiments.items():
